"""Small standard-library KDL reader for Dasel's common document subset."""
import re

_TOKEN = re.compile(r'[ \t]*(?:(//[^\n]*)|("(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\')|([{};=])|([^\s{};=]+))')


def _scalar(s):
    if s.startswith('"') or s.startswith("'"):
        if s.startswith('"'):
            try:
                import json
                return json.loads(s)
            except Exception:
                pass
        return s[1:-1]
    if s in ('#true', '#false', '#null', '#nan', '#inf', '#-inf'):
        return {'#true': True, '#false': False, '#null': None, '#nan': float('nan'), '#inf': float('inf'), '#-inf': -float('inf')}[s]
    if s.startswith('#'):
        return s[1:]
    try:
        numeric=s.replace('_','')
        if re.fullmatch(r'[+-]?0[xX][0-9a-fA-F_]+|[+-]?0[oO][0-7_]+|[+-]?0[bB][01_]+', s):
            sign = -1 if numeric.startswith('-') else 1
            return sign * int(numeric.lstrip('+-'), 0)
        if re.fullmatch(r'[+-]?[0-9][0-9_]*', s):
            return int(numeric)
        if re.fullmatch(r'[+-]?(?:[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+[eE][+-]?[0-9]+|[0-9]+\.[0-9]*[eE][+-]?[0-9]+)', numeric):
            return float(numeric)
    except ValueError:
        pass
    return s


def loads(source):
    toks=[]
    i=0
    while i < len(source):
        if source[i] in ' \t':
            i+=1; continue
        if source.startswith('/*', i):
            depth=1; i+=2
            while i<len(source) and depth:
                if source.startswith('/*',i): depth+=1; i+=2
                elif source.startswith('*/',i): depth-=1; i+=2
                else: i+=1
            if depth: break
            continue
        if source[i]=='(':
            end=source.find(')',i+1)
            if end>=0:
                i=end+1; continue
        raw_prefix=re.match(r'r(#+)?\"',source[i:])
        if raw_prefix:
            hashes=raw_prefix.group(1) or ''
            start=i+raw_prefix.end()
            close='\"'+hashes
            end=source.find(close,start)
            if end < 0: break
            toks.append(('VAL',source[start:end])); i=end+len(close); continue
        if source[i] == '\n' or source[i] == '\r':
            if source[i] == '\r' and i+1 < len(source) and source[i+1]=='\n': i+=1
            toks.append(('NL','')); i+=1; continue
        m=_TOKEN.match(source,i)
        if not m:
            i+=1; continue
        i=m.end()
        comment, quoted, punct, word=m.groups()
        if comment: continue
        if punct:
            toks.append((punct,punct))
        elif quoted:
            toks.append(('VAL',quoted))
        elif word:
            toks.append(('VAL',word))
    pos=0
    def add(out,key,val):
        if key not in out: out[key]=val
        elif isinstance(out[key],list): out[key].append(val)
        else: out[key]=[out[key],val]
    def block(stop=False):
        nonlocal pos
        obj={}
        while pos<len(toks):
            while pos<len(toks) and toks[pos][0] in ('NL',';'): pos+=1
            if pos>=len(toks): break
            if toks[pos][0]=='}':
                pos+=1
                if stop: return obj
                continue
            if toks[pos][0]!='VAL': pos+=1; continue
            name=_scalar(toks[pos][1]); pos+=1
            if not isinstance(name,str): name=str(name)
            props={}; args=[]
            while pos<len(toks) and toks[pos][0] not in ('NL',';','{','}'):
                if toks[pos][0]=='VAL':
                    val=toks[pos][1]; pos+=1
                    if pos<len(toks) and toks[pos][0]=='=':
                        pos+=1
                        if pos<len(toks) and toks[pos][0]=='VAL':
                            props[str(_scalar(val))]=_scalar(toks[pos][1]); pos+=1
                    else: args.append(_scalar(val))
                else: pos+=1
            has_children = pos<len(toks) and toks[pos][0]=='{'
            children = {}
            if has_children:
                pos+=1; children=block(True)
            if has_children:
                value=dict(children)
                value.update(props)
                if args: value['$args']=args
                if not value: value=None
            elif props:
                value=props
                if args: value['$args']=args
            elif len(args)==1: value=args[0]
            elif args: value={'$args':args}
            else: value=None
            add(obj,name,value)
            if pos<len(toks) and toks[pos][0]=='}' and not stop:
                pos+=1
        return obj
    if not any(kind not in ('NL',';') for kind,_ in toks): return None
    return block()


def dumps(value):
    """Serialize JSON-like data using KDL nodes and properties."""
    import json
    import math
    def atom(v):
        if v is None: return '#null'
        if v is True: return '#true'
        if v is False: return '#false'
        if isinstance(v, str): return json.dumps(v, ensure_ascii=False)
        if isinstance(v, (int,float)):
            if isinstance(v,float) and math.isnan(v): return '#nan'
            if isinstance(v,float) and math.isinf(v): return '#inf' if v > 0 else '#-inf'
            return str(v)
        return json.dumps(str(v),ensure_ascii=False)
    def name(n):
        n=str(n)
        if re.fullmatch(r'[^\s{};=\[\]"\\]+',n): return n
        return json.dumps(n,ensure_ascii=False)
    lines=[]
    def node(k,v,depth=0):
        pad='  '*depth; base=pad+name(k)
        if isinstance(v,list):
            for x in v: node(k,x,depth)
            return
        if isinstance(v,dict):
            props=[]; kids=[]
            for ck,cv in v.items():
                if isinstance(cv,dict): kids.append((ck,cv))
                elif isinstance(cv,list) and any(isinstance(x,(dict,list)) for x in cv): kids.append((ck,cv))
                elif isinstance(cv,list):
                    # Scalar arrays are encoded as repeated child nodes.
                    kids.append((ck,cv))
                else: props.append((ck,cv))
            for pk,pv in props:
                base+=' '+name(pk)+'='+atom(pv)
            if kids:
                lines.append(base+' {')
                for ck,cv in kids: node(ck,cv,depth+1)
                lines.append(pad+'}')
            else: lines.append(base)
            return
        val='' if v is None else atom(v)
        lines.append(base+(' '+val if val else ''))
    if isinstance(value,dict):
        for k,v in value.items(): node(k,v)
    elif isinstance(value,list):
        if any(isinstance(v,(dict,list)) for v in value):
            raise ValueError('kdl: cannot convert map to KDL value')
        lines.append('root'+(' '+' '.join(atom(v) for v in value) if value else ''))
    else:
        node('root',value)
    return '\n'.join(lines)+('\n' if lines else '')

