"""Small standard-library TOML adapter used by the CLI implementation."""
from __future__ import annotations

import json
import math
try:
    import tomllib
except ImportError:  # Python 3.10
    tomllib = None
from typing import Any


def parse_toml(text: str) -> Any:
    if tomllib is not None:
        return tomllib.loads(text)
    def split_top(s: str, delimiter: str) -> list[str]:
        out=[]; start=0; depth=0; quote=None; escape=False
        for i,c in enumerate(s):
            if quote:
                if escape: escape=False
                elif c=='\\' and quote=='"': escape=True
                elif c==quote: quote=None
            elif c in "\"'": quote=c
            elif c in "[{": depth+=1
            elif c in "]}": depth-=1
            elif c==delimiter and depth==0:
                out.append(s[start:i].strip()); start=i+1
        out.append(s[start:].strip())
        return out

    def value_of(s: str) -> Any:
        s=s.strip()
        try: return json.loads(s)
        except Exception: pass
        if s.startswith("'") and s.endswith("'"): return s[1:-1].replace("''", "'")
        low=s.lower()
        if low in ("true","false"): return low=="true"
        if s.startswith("[") and s.endswith("]"):
            body=s[1:-1].strip()
